    if ((c_bi == NULL) || (body_vectors == NULL) || (inertial_vectors == NULL) || 
        (weights == NULL) || (loss == NULL) || (worst_index == NULL)) {
        return ADCS_E_NULL;
    }

    if (count < 1 || count > 32) {
        return ADCS_E_RANGE;
    }

    // Validate matrix finiteness
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            if (!isfinite(c_bi->m[i][j])) {
                return ADCS_E_RANGE;
            }
        }
    }

    double sum_w = 0.0;
    double weighted_loss_sum = 0.0;
    double max_e = -1.0;
    size_t worst_idx = SIZE_MAX;

    for (size_t k = 0; k < count; ++k) {
        adcs_vec3_t v_inertial_raw = inertial_vectors[k];
        adcs_vec3_t v_body_raw = body_vectors[k];
        double w = weights[k];

        // Validate vector finiteness
        if (!adcs_is_finite_vec3(&v_inertial_raw) || !adcs_is_finite_vec3(&v_body_raw)) {
            return ADCS_E_RANGE;
        }

        // Validate weight
        if (!isfinite(w) || w <= 0.0) {
            return ADCS_E_RANGE;
        }

        // Normalize inertial vector to get r_k
        adcs_vec3_t r_k;
        if (adcs_vec3_normalize(&v_inertial_raw, ADCS_EPS_NORM, &r_k) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Predicted body vector: p_k = C_BI * r_k
        adcs_vec3_t p_k = adcs_mat3_mul_vec(c_bi, &r_k);

        // Normalize body vector to get b_k
        adcs_vec3_t b_k;
        if (adcs_vec3_normalize(&v_body_raw, ADCS_EPS_NORM, &b_k) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Residual e_k = 1 - b_k . p_k
        double dot_product = adcs_vec3_dot(&b_k, &p_k);
        double e_k = 1.0 - dot_product;

        // Accumulate
        sum_w += w;
        weighted_loss_sum += w * e_k;

        // Find worst observation (largest unweighted e_k, lowest index on tie)
        if (e_k > max_e) {
            max_e = e_k;
            worst_idx = k;
        }
    }

    // Calculate final loss
    if (sum_w <= 0.0) {
        *loss = INFINITY;
    } else {
        *loss = weighted_loss_sum / sum_w;
    }

    *worst_index = worst_idx;

    return ADCS_OK;
}

